function TrackDialog({data,track,onClose,onSubmit}:{data:Setup;track:Track|null;onClose:()=>void;onSubmit:(p:Record<string,unknown>)=>Promise<void>}) { const base=track?{title:track.title,isActive:track.isActive?"نشط":"غير نشط"}:{isActive:"نشط"};let extras:Record<string,unknown>={};try{extras=track?JSON.parse(track.customData||"{}"):{};}catch{extras={}}const [values,setValues]=useState<Record<string,unknown>>({...extras,...base});const [busy,setBusy]=useState(false);const [error,setError]=useState("");async function submit(event:FormEvent){event.preventDefault();setBusy(true);setError("");try{await onSubmit(values)}catch(reason){setError(reason instanceof Error?reason.message:"تعذر حفظ الـTrack");setBusy(false)}}return <div className="overlay" onMouseDown={(event)=>event.target===event.currentTarget&&onClose()}><form className="dialog track-dialog" onSubmit={submit}><div className="dialog-head"><div><span className="dialog-icon">◇</span><div><h2>{track?"تعديل Track":"إضافة Track جديدة"}</h2><p>اسم المسار وحالته داخل النظام.</p></div></div><button type="button" onClick={onClose}>×</button></div>{error&&<p className="form-error">{error}</p>}<div className="employee-form-note"><span>↻</span><p>النموذج ديناميكي، والـTracks النشطة تظهر فورًا داخل نموذج الـLead.</p></div><div className="dynamic-grid dialog-fields">{data.trackFields.filter((field)=>field.visible).map((field)=><DynamicField key={field.id} field={field} value={values[field.fieldKey]} setValue={(value)=>setValues((current)=>({...current,[field.fieldKey]:value}))} data={data} values={values}/>)}</div><div className="dialog-foot"><button className="secondary" type="button" onClick={onClose}>إلغاء</button><button className="primary" disabled={busy}>{busy?"جارٍ الحفظ...":track?"حفظ التعديلات":"إضافة الـTrack"}</button></div></form></div>;}
